App.my.KEY = 'duty';
App.my.KINDS = [['day', '☀️ పగలు'], ['night', '🌙 రాత్రి'], ['second', '🌇 సెకండ్'], ['extra', '➕ ఎక్స్‌ట్రా'], ['leave', '🏖️ సెలవు']];
App.my.label = (k) => (App.my.KINDS.find((x) => x[0] === k) || ['', k])[1];
App.my.set = () => Object.assign({ hours: 8 }, App.load('duty-set', {}));
App.my.month = (key) => App.items(App.my.KEY).filter((d) => App.monthKey(d.date) === key);
App.my.byDate = (date) => App.items(App.my.KEY).find((d) => d.date === date);
App.my.count = (l) => {
  const c = { work: 0, night: 0, extra: 0, leave: 0, hours: 0, ot: 0 };
  l.forEach((d) => {
    if (d.kind === 'leave') { c.leave++; return; }
    c.work++; if (d.kind === 'night') c.night++; if (d.kind === 'extra') c.extra++;
    c.hours += Number(d.hours) || 0; c.ot += Number(d.ot) || 0;
  });
  return c;
};
App.my.put = (date, rec) => { const old = App.my.byDate(date); if (old) App.update(App.my.KEY, old.id, rec); else App.add(App.my.KEY, Object.assign({ date }, rec)); };
App.my.kindOf = (w) => {
  const t = String(w || '').toLowerCase();
  if (/రాత్రి|night|నైట్/.test(t)) return 'night';
  if (/సెకండ్|second|సాయంత్రం|evening/.test(t)) return 'second';
  if (/ఎక్స్‌?ట్రా|extra|అదనపు|ఓవర్/.test(t)) return 'extra';
  if (/సెలవు|leave|off|రెస్ట్|lv/.test(t)) return 'leave';
  return 'day';
};
App.my.widget = async () => {
  const c = App.my.count(App.my.month(App.monthKey(new Date())));
  try { await App.widget('🗓️ డ్యూటీ', ['ఈ నెల ' + c.work + ' డ్యూటీలు · 🌙 ' + c.night, (c.ot ? 'OT ' + App.n(c.ot, 1) + ' గం · ' : '') + c.leave + ' సెలవులు']); } catch (e) { /* the widget only helps */ }
};
App.onStart(() => { App.my.widget(); });
App.onJarvis('add', (d) => {
  const date = /^\d{4}-\d{2}-\d{2}$/.test(String(d.date || '')) ? d.date : App.today(), kind = App.my.kindOf(d.kind);
  const ot = Number(d.ot) > 0 ? Number(d.ot) : 0;
  App.my.put(date, { kind, hours: kind === 'leave' ? 0 : App.my.set().hours, ot });
  App.my.widget();
  return App.date(date, 'short') + ' ' + App.my.label(kind) + (ot ? ', OT ' + App.n(ot, 1) + ' గంటలు' : '') + ' రాశాను';
});

App.onShow('home', () => {
  const l = App.my.month(App.monthKey(new Date())), c = App.my.count(l), t = App.my.byDate(App.today());
  App.text('#home-work', String(c.work));
  App.text('#home-night', String(c.night));
  App.text('#home-ot', App.n(c.ot, 1));
  App.text('#home-leave', String(c.leave));
  App.text('#home-today', t ? App.my.label(t.kind) + (t.ot ? ' · OT ' + App.n(t.ot, 1) : '') : 'ఇంకా రాయలేదు');
  App.set('#home-quick', App.my.KINDS.map((k) => `<button class="btn small${t && t.kind === k[0] ? ' primary' : ''}" data-k="${k[0]}">${k[1]}</button>`).join(''));
  const days = l.sort((a, b) => (b.date || '').localeCompare(a.date || ''));
  App.set('#home-list', days.length ? '<div class="list">' + days.map((d) => `
    <div class="item" data-id="${App.esc(d.id)}">
      <div class="ic">${App.esc(App.my.label(d.kind).split(' ')[0])}</div>
      <div class="w"><div class="t">${App.esc(App.my.label(d.kind).split(' ').slice(1).join(' '))}${d.kind !== 'leave' && d.hours ? ' · ' + App.esc(App.n(d.hours, 1)) + ' గం' : ''}${d.ot ? ' · OT ' + App.esc(App.n(d.ot, 1)) : ''}</div>
        <div class="s">${App.date(d.date, 'day')}${d.note ? ' · ' + App.esc(d.note) : ''}</div></div>
    </div>`).join('') + '</div>'
    : '<div class="empty"><div class="e">🗓️</div>ఈ నెల ఇంకా ఏమీ రాయలేదు. పైన ఈరోజు డ్యూటీ నొక్కండి.</div>');
});
App.click('#home-quick .btn', (ev, el) => {
  const kind = el.dataset.k;
  App.my.put(App.today(), { kind, hours: kind === 'leave' ? 0 : App.my.set().hours, ot: (App.my.byDate(App.today()) || {}).ot || 0 });
  App.my.widget(); App.beep('ok'); App.toast('ఈరోజు: ' + App.my.label(kind)); App.refresh();
});
App.click('#home-add', () => App.go('shift'));
App.click('#home-list .item', (ev, el) => App.go('shift', App.find(App.my.KEY, el.dataset.id)));

App.onShow('shift', (d) => {
  App.my.editing = d && d.id ? d.id : null;
  App.title(App.my.editing ? 'రోజు మార్చండి' : 'ఒక రోజు రాయండి');
  App.val('#shift-date', d && d.date ? d.date : App.today());
  App.val('#shift-kind', d && d.kind ? d.kind : 'day');
  App.val('#shift-h', d ? d.hours : App.my.set().hours);
  App.val('#shift-ot', d && d.ot ? d.ot : '');
  App.val('#shift-note', d && d.note ? d.note : '');
  App.show('#shift-del', !!App.my.editing);
});
App.click('#shift-save', () => {
  const kind = App.val('#shift-kind') || 'day', hours = Number(App.val('#shift-h')) || 0, ot = Number(App.val('#shift-ot')) || 0;
  if (hours < 0 || hours > 24 || ot < 0 || ot > 24) { App.toast('గంటలు 0–24 లో రాయండి'); return; }
  const rec = { date: App.val('#shift-date') || App.today(), kind, hours: kind === 'leave' ? 0 : hours, ot, note: App.val('#shift-note') };
  if (App.my.editing) App.update(App.my.KEY, App.my.editing, rec); else App.my.put(rec.date, rec);
  App.my.widget(); App.beep('ok'); App.toast('దాచాను'); App.back();
});
App.click('#shift-del', async () => {
  if (!App.my.editing) return;
  if (await App.ask('ఈ రోజు తీసేయాలా?', 'తీసేయి', 'వద్దు')) { App.del(App.my.KEY, App.my.editing); App.my.widget(); App.toast('తీసేశాను'); App.back(); }
});

App.my.keys = (n) => { const ks = []; for (let i = n - 1; i >= 0; i--) { const d = new Date(); d.setDate(1); d.setMonth(d.getMonth() - i); ks.push(App.monthKey(d)); } return ks; };
App.onShow('stats', () => {
  const ks = App.my.keys(6);
  App.chart('#stats-chart', { type: 'bar', labels: ks.map((k) => App.month(k + '-01').split(' ')[0]), values: ks.map((k) => App.my.count(App.my.month(k)).work) });
  const rows = App.my.keys(12).reverse().filter((k) => App.my.month(k).length);
  App.set('#stats-list', rows.length ? '<div class="list">' + rows.map((k) => {
    const c = App.my.count(App.my.month(k));
    return `<div class="item"><div class="ic">📅</div><div class="w"><div class="t">${App.esc(App.month(k + '-01'))}</div>
      <div class="s">🌙 ${c.night} రాత్రి · ➕ ${c.extra} ఎక్స్‌ట్రా · 🏖️ ${c.leave} సెలవు${c.ot ? ' · OT ' + App.n(c.ot, 1) + ' గం' : ''}</div></div><div class="r">${c.work}</div></div>`;
  }).join('') + '</div>' : '<div class="empty"><div class="e">📊</div>ఇంకా నెలలు లేవు.</div>');
  App.text('#stats-set-s', 'ఇప్పుడు: ' + App.n(App.my.set().hours, 1) + ' గంటలు');
  App.my.drawRem();
});
App.my.next9 = () => { const d = new Date(); d.setHours(21, 0, 0, 0); if (d.getTime() < Date.now()) d.setDate(d.getDate() + 1); return App.ymd(d) + ' 21:00'; };
App.my.drawRem = async () => {
  let on = false;
  try { on = (await App.reminders()).some((r) => r.id === 'daily'); } catch (e) { /* */ }
  App.my.remOn = on;
  App.text('#stats-rem', on ? 'తీసేయి' : 'పెట్టు');
  App.text('#stats-rem-s', on ? 'పెట్టారు: రోజూ రాత్రి 9 కి' : '"ఈరోజు డ్యూటీ రాశారా?" అని');
};
App.click('#stats-rem', async () => {
  try {
    if (App.my.remOn) { await App.unremind('daily'); App.toast('రిమైండర్ తీసేశాను'); }
    else { await App.remind({ id: 'daily', when: App.my.next9(), every: 'day', title: '🗓️ డ్యూటీ లెక్క', text: 'ఈరోజు డ్యూటీ రాశారా?', screen: 'home' }); App.toast('రోజూ రాత్రి 9 కి గుర్తు చేస్తాను'); }
  } catch (e) { App.toast('రిమైండర్ పెట్టలేకపోయాను'); }
  App.my.drawRem();
});
App.click('#stats-set', async () => {
  const v = await App.input('ఒక డ్యూటీ ఎన్ని గంటలు?', { type: 'number', value: App.my.set().hours });
  if (v == null) return;
  const h = Number(v);
  if (!(h > 0 && h <= 24)) { App.toast('1–24 లో రాయండి'); return; }
  App.save('duty-set', { hours: h }); App.toast('మార్చాను'); App.refresh();
});
App.my.thisMonth = () => App.my.month(App.monthKey(new Date())).sort((a, b) => (a.date || '').localeCompare(b.date || ''));
App.click('#stats-share', async () => {
  const c = App.my.count(App.my.thisMonth());
  const t = '🗓️ ' + App.month(App.today()) + ' డ్యూటీ: ' + c.work + ' డ్యూటీలు (🌙 ' + c.night + ' రాత్రి, ➕ ' + c.extra + ' ఎక్స్‌ట్రా), 🏖️ ' + c.leave + ' సెలవులు' + (c.ot ? ', OT ' + App.n(c.ot, 1) + ' గంటలు' : '');
  try { await App.share(t); } catch (e) { App.toast('షేర్ కాలేదు'); }
});
App.click('#stats-pdf', async () => {
  const l = App.my.thisMonth(), c = App.my.count(l);
  const rows = l.map((d) => `<tr><td>${App.date(d.date, 'day')}</td><td>${App.esc(App.my.label(d.kind))}</td><td class="n">${d.kind === 'leave' ? '' : App.n(d.hours, 1)}</td><td class="n">${d.ot ? App.n(d.ot, 1) : ''}</td><td>${App.esc(d.note || '')}</td></tr>`).join('');
  const html = `<h2>${App.esc(App.month(App.today()))} డ్యూటీ</h2><p>${c.work} డ్యూటీలు · 🌙 ${c.night} · ➕ ${c.extra} · 🏖️ ${c.leave}${c.ot ? ' · OT ' + App.n(c.ot, 1) + ' గం' : ''}</p>`
    + `<table><tr><th>తేదీ</th><th>డ్యూటీ</th><th>గంటలు</th><th>OT</th><th>నోట్</th></tr>${rows}</table>`;
  try { await App.pdf('డ్యూటీ ' + App.monthKey(new Date()), html); } catch (e) { App.toast('PDF కాలేదు'); }
});
